{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C02","C01","C06","C12","C14","C18","C19","C23","C24","C03","C08","C05","C09","C16","C13","C20","C25"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C02","C01","C06","C12","C14","C18","C19","C23","C24","C03","C08","C05","C09","C16","C13","C20","C25"],
  "claims": [
    {
      "claim": "The closest structural context, a fused pyrazolopyrimidinone lactam bearing a pyridine sulfonamide-linked basic piperazine, showed 34% oral bioavailability derived from IV and oral profiles in fasted healthy volunteers, directly supporting F >= 20% for a sulfonamide-linked basic amine on a fused lactam.",
      "card_ids": ["C02"]
    },
    {
      "claim": "Ziprasidone, a fused oxindole lactam with a basic piperazine side chain, had 30% fasted-state and ~60% fed-state absolute oral bioavailability, all above the 20% threshold.",
      "card_ids": ["C01","C06","C12","C14","C18","C19","C23","C24"]
    },
    {
      "claim": "Praziquantel, an isoquinolinone-type lactam, retained 27.2 ± 5.4% oral bioavailability even in cirrhotic patients, supporting positive oral exposure for isoquinolinone-related structures.",
      "card_ids": ["C03"]
    },
    {
      "claim": "Other training contexts are also at or above threshold: niraparib ~73% fasted, didanosine 29 ± 6% fasted, thalidomide 80-100%, and gaboxadol high in humans with 83-110% in rats.",
      "card_ids": ["C08","C05","C09","C16","C13","C20","C25"]
    },
    {
      "claim": "L3 oral exposure records for related basic amine lactams/quinolones (ciprofloxacin, palonosetron, sildenafil metabolite, NM394, nemiralisib) show measurable oral Cmax/AUC, but none provides a direct F value for the query or an affirmative low-F result.",
      "card_ids": ["C26","C27","C28","C29","C30","C31","C32","C33","C34","C35","C36","C37"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C26","C27","C28","C29","C30","C31","C32","C33","C34","C35","C36","C37"]
    }
  ],
  "evidence_gaps": [
    "No direct query-specific absolute oral bioavailability measurement is available.",
    "No human PK, formulation, prandial-state, or IV-comparison data for the exact query molecule are supplied.",
    "L3 records are exposure-only (Cmax/AUC) for other molecules and do not provide F values; C26/C34 describe a sucralfate interaction, not query-relevant.",
    "Metabolic stability, first-pass extraction, and transporter/efflux behavior for the query are not directly measured.",
    "The query's very low neutral fraction and logD -1.42 raise permeability uncertainty, but this is not affirmative evidence of F < 20%.",
    "Transfer from C02, ziprasidone, praziquantel, and L3 exposure molecules is structural/functional rather than an exact match."
  ],
  "decision_summary": "Prediction remains high: the closest structural context (C02) and multiple lactam/basic-amine training contexts report F at or above 20%, and L3 oral exposure records for related basic amine lactams show measurable oral Cmax/AUC without any affirmative low-F evidence. The mixed physicochemical prior is insufficient to overturn this, so F >= 20% is better supported; confidence moderate."
}

